state.indication_core:
#include "cold-indication.h"

_Static_assert(sizeof(struct npu_cold_indication_state) == 32, "indication state changed");

static uint32_t load(const uint32_t *word)
{
    return __atomic_load_n(word, __ATOMIC_ACQUIRE);
}

void npu_cold_indication_fault(struct npu_cold_indication_state *s)
{
    if (s)
        __atomic_store_n(&s->fault, 1, __ATOMIC_RELEASE);
}

static uint32_t fail(struct npu_cold_indication_state *s, uint32_t error)
{
    npu_cold_indication_fault(s);
    return error;
}

static int plan_valid(const struct npu_cold_indication_plan *p,
                      const volatile uint32_t *words)
{
    return p && words && !((uintptr_t)words & 3) &&
           !(p->base & 31) && p->base >= 0x3e800000u &&
           p->base <= 0x3e878000u - NPU_COLD_INDICATION_BYTES &&
           p->bytes == NPU_COLD_INDICATION_BYTES;
}

static uint32_t valid(struct npu_cold_indication_state *s,
    const struct npu_cold_indication_plan *p, uint32_t epoch,
    const volatile uint32_t *words)
{
    if (!s)
        return NPU_COLD_INDICATION_ARGUMENT;
    if (load(&s->fault))
        return NPU_COLD_INDICATION_FAULT;
    if (!plan_valid(p, words) || s->magic != NPU_COLD_INDICATION_MAGIC ||
        s->epoch != 1 || s->active != 1 || s->base != p->base ||
        s->count != NPU_COLD_INDICATION_COUNT ||
        s->committed > s->count || s->published > s->committed ||
        s->committed - s->published > 1)
        return fail(s, NPU_COLD_INDICATION_CORRUPT);
    return epoch == s->epoch ? NPU_COLD_INDICATION_OK : NPU_COLD_INDICATION_STALE;
}

uint32_t npu_cold_indication_begin(struct npu_cold_indication_state *s,
    const struct npu_cold_indication_plan *p, uint32_t epoch,
    const volatile uint32_t *words)
{
    uint32_t i;

    if (!s)
        return NPU_COLD_INDICATION_ARGUMENT;
    if (s->magic || s->epoch || load(&s->fault) || s->active ||
        s->committed || s->published || s->base || s->count)
        return NPU_COLD_INDICATION_REINITIALIZE;
    if (epoch != 1 || !plan_valid(p, words))
        return fail(s, NPU_COLD_INDICATION_PLAN);
    for (i = 0; i < NPU_COLD_INDICATION_COUNT * 2; i++)
        if (words[i])
            return fail(s, NPU_COLD_INDICATION_FRESHNESS);
    s->epoch = epoch;
    s->base = p->base;
    s->count = NPU_COLD_INDICATION_COUNT;
    s->active = 1;
    __atomic_store_n(&s->magic, NPU_COLD_INDICATION_MAGIC, __ATOMIC_RELEASE);
    return load(&s->fault) ? NPU_COLD_INDICATION_FAULT : NPU_COLD_INDICATION_OK;
}

uint32_t npu_cold_indication_reserve(struct npu_cold_indication_state *s,
    const struct npu_cold_indication_plan *p, uint32_t epoch,
    uint32_t address, uint32_t value, const volatile uint32_t *words)
{
    uint32_t status = valid(s, p, epoch, words), index;

    if (status)
        return status;
    index = s->committed;
    if (index != s->published || index == s->count ||
        address != s->base + index * 8 || value != NPU_COLD_INDICATION_STATUS ||
        words[index * 2] || words[index * 2 + 1])
        return fail(s, NPU_COLD_INDICATION_ORDER);
    /* A store can become visible before readback or a later caller check. */
    __atomic_store_n(&s->committed, index + 1, __ATOMIC_RELEASE);
    return load(&s->fault) ? NPU_COLD_INDICATION_FAULT : NPU_COLD_INDICATION_OK;
}

uint32_t npu_cold_indication_pending(struct npu_cold_indication_state *s,
    const struct npu_cold_indication_plan *p, uint32_t epoch,
    uint32_t address, uint32_t value, const volatile uint32_t *words)
{
    uint32_t status = valid(s, p, epoch, words), index;

    if (status)
        return status;
    index = s->published;
    if (s->committed != index + 1 || index == s->count ||
        address != s->base + index * 8 || value != NPU_COLD_INDICATION_STATUS ||
        words[index * 2] || words[index * 2 + 1])
        return fail(s, NPU_COLD_INDICATION_ORDER);
    return NPU_COLD_INDICATION_OK;
}

uint32_t npu_cold_indication_publish(struct npu_cold_indication_state *s,
    const struct npu_cold_indication_plan *p, uint32_t epoch,
    uint32_t address, const volatile uint32_t *words)
{
    uint32_t status = valid(s, p, epoch, words), index;

    if (status)
        return status;
    index = s->published;
    if (s->committed != index + 1 || index == s->count ||
        address != s->base + index * 8 || words[index * 2] ||
        words[index * 2 + 1] != NPU_COLD_INDICATION_STATUS)
        return fail(s, NPU_COLD_INDICATION_PUBLISH);
    __atomic_store_n(&s->published, index + 1, __ATOMIC_RELEASE);
    return load(&s->fault) ? NPU_COLD_INDICATION_FAULT : NPU_COLD_INDICATION_OK;
}

uint32_t npu_cold_indication_finish(struct npu_cold_indication_state *s,
    const struct npu_cold_indication_plan *p, uint32_t epoch,
    const volatile uint32_t *words)
{
    uint32_t status = valid(s, p, epoch, words), i;

    if (status)
        return status;
    if (s->committed != s->count || s->published != s->count)
        return fail(s, NPU_COLD_INDICATION_ORDER);
    for (i = 0; i < s->count; i++)
        if (words[i * 2] || words[i * 2 + 1] != NPU_COLD_INDICATION_STATUS)
            return fail(s, NPU_COLD_INDICATION_PUBLISH);
    s->active = 0;
    return load(&s->fault) ? NPU_COLD_INDICATION_FAULT : NPU_COLD_INDICATION_OK;
}

state.indication_header:
#ifndef W1700K_NPU_COLD_INDICATION_H
#define W1700K_NPU_COLD_INDICATION_H

#include <stdint.h>

#define NPU_COLD_INDICATION_MAGIC 0x31444e49u
#define NPU_COLD_INDICATION_COUNT 1536u
#define NPU_COLD_INDICATION_BYTES (NPU_COLD_INDICATION_COUNT * 8u)
#define NPU_COLD_INDICATION_STATUS 0xe0000000u

struct npu_cold_indication_plan {
    uint32_t base, bytes;
};

struct npu_cold_indication_state {
    uint32_t magic, epoch, fault, active;
    uint32_t committed, published, base, count;
};

enum npu_cold_indication_status {
    NPU_COLD_INDICATION_OK,
    NPU_COLD_INDICATION_ARGUMENT,
    NPU_COLD_INDICATION_PLAN,
    NPU_COLD_INDICATION_REINITIALIZE,
    NPU_COLD_INDICATION_FAULT,
    NPU_COLD_INDICATION_STALE,
    NPU_COLD_INDICATION_CORRUPT,
    NPU_COLD_INDICATION_FRESHNESS,
    NPU_COLD_INDICATION_ORDER,
    NPU_COLD_INDICATION_PUBLISH,
};

/* The coordinator supplies an immutable reserved span and its valid, nonaliasing
 * word view under a held epoch1 lease. Reserve precedes the native store; publish
 * follows readback. Faults retain the reservation/committed prefix. No reset,
 * retirement, DMA grant, cache or earlier-user exclusion is established here. */
uint32_t npu_cold_indication_begin(struct npu_cold_indication_state *state,
    const struct npu_cold_indication_plan *plan, uint32_t epoch,
    const volatile uint32_t *words);
uint32_t npu_cold_indication_reserve(struct npu_cold_indication_state *state,
    const struct npu_cold_indication_plan *plan, uint32_t epoch,
    uint32_t address, uint32_t value, const volatile uint32_t *words);
uint32_t npu_cold_indication_publish(struct npu_cold_indication_state *state,
    const struct npu_cold_indication_plan *plan, uint32_t epoch,
    uint32_t address, const volatile uint32_t *words);
uint32_t npu_cold_indication_pending(struct npu_cold_indication_state *state,
    const struct npu_cold_indication_plan *plan, uint32_t epoch,
    uint32_t address, uint32_t value, const volatile uint32_t *words);
uint32_t npu_cold_indication_finish(struct npu_cold_indication_state *state,
    const struct npu_cold_indication_plan *plan, uint32_t epoch,
    const volatile uint32_t *words);
void npu_cold_indication_fault(struct npu_cold_indication_state *state);

#endif

state.native_adapter:
/* Guarded native indication initialization; physical contracts remain external. */
#include "allocator.h"
#include "cold-indication.h"
#include "cold-setup.h"

extern struct npu_bootstrap npu_emulation_bootstrap_state;
extern struct npu_admission npu_emulation_admission_state;
extern struct npu_barrier npu_emulation_barrier_state;
extern struct npu_cold_setup npu_emulation_cold_setup_state;
extern uint32_t npu_original_page_dispatch(uint32_t count, uint32_t selector);
extern int npu_emulation_cold_arena_live(void);

struct npu_cold_indication_state npu_emulation_indication_state;
struct npu_cold_indication_plan npu_emulation_indication_plan;
static uint32_t arena, record_index, allocation_count, allocation_used;
static uint32_t identity[5];
static uint32_t lock_owned;
static const uint32_t lock_id = 18;

#define SETUP (&npu_emulation_cold_setup_state)
#define OWNER (&npu_emulation_indication_state)
#define PLAN (&npu_emulation_indication_plan)
#define METADATA ((const struct npu_allocator_state *)(uintptr_t)0x3e901bccu)

static uint32_t word(uint32_t address)
{
    return *(const volatile uint32_t *)(uintptr_t)address;
}

static uint32_t fail(void)
{
    npu_cold_indication_fault(OWNER);
    npu_admission_fail(&npu_emulation_admission_state, &npu_emulation_barrier_state);
    return 0;
}

static int context(void)
{
    static const uint32_t limits[NPU_COLD_COUNTS] = {1536, 1024, 256, 512, 1024};
    uint32_t i;

    if (!npu_emulation_cold_arena_live() || SETUP->failed || SETUP->inflight != 1 ||
        SETUP->completed != 4095 || SETUP->command.header != 0x18 ||
        SETUP->command.api != 1 || SETUP->command.value != NPU_COLD_INDICATION_COUNT ||
        SETUP->endpoint_base != SETUP->prior_base || SETUP->endpoint_bytes != SETUP->prior_bytes ||
        word(0x3e902a9cu) != SETUP->endpoint_base + NPU_COLD_IND_REG ||
        word(0x8401cf38u) != 6 || word(0x8401cf3cu) != 0x1f020 ||
        word(0x8401cfc8u) != 1 || word(0x8401cfccu) != 303168 ||
        METADATA->lock_id != 18 || METADATA->count > NPU_ALLOCATOR_ENTRIES)
        return 0;
    for (i = 0; i < NPU_COLD_COUNTS; i++)
        if (SETUP->counts[i] != limits[i] || SETUP->prior_counts[i] != limits[i])
            return 0;
    return 1;
}

static int owned(void)
{
    const struct npu_allocator_entry *entry;

    if (!lock_owned || !context() || word(0x3e9030fcu) != arena || PLAN->base != arena + 0x1f020u ||
        PLAN->bytes != NPU_COLD_INDICATION_BYTES || record_index >= METADATA->count ||
        METADATA->count != allocation_count || METADATA->used != allocation_used ||
        SETUP->sequence != identity[0] || SETUP->boot_lo != identity[1] ||
        SETUP->boot_hi != identity[2] || SETUP->nonce_lo != identity[3] || SETUP->nonce_hi != identity[4])
        return 0;
    entry = &METADATA->entries[record_index];
    return entry->type == 1 && !entry->reserved && entry->address == arena;
}

static const volatile uint32_t *words(void)
{
    return (const volatile uint32_t *)(uintptr_t)PLAN->base;
}

uint32_t npu_emulation_indication_reserve(uint32_t address)
{
    if (!owned() || word(0x3e902aa0u) != PLAN->base ||
        npu_cold_indication_reserve(OWNER, PLAN, 1, address,
            NPU_COLD_INDICATION_STATUS, words()) != NPU_COLD_INDICATION_OK)
        return fail();
    return 1;
}

uint32_t npu_emulation_indication_pending(uint32_t address, uint32_t value)
{
    if (!owned() || word(0x3e902aa0u) != PLAN->base ||
        npu_cold_indication_pending(OWNER, PLAN, 1, address, value, words()) != NPU_COLD_INDICATION_OK)
        return fail();
    return 1;
}

uint32_t npu_emulation_indication_publish(uint32_t address)
{
    if (!owned() || word(0x3e902aa0u) != PLAN->base ||
        npu_cold_indication_publish(OWNER, PLAN, 1, address, words()) != NPU_COLD_INDICATION_OK)
        return fail();
    return 1;
}

uint32_t npu_emulation_indication_callback(const struct npu_bootstrap_packet *packet)
{
    struct npu_bootstrap_packet snapshot;
    uint32_t status, result = 0, matches = 0, i;

    __asm__ volatile ("csrrci %0, mstatus, 8" : "=r"(status) :: "memory");
    snapshot = *packet;
    if (snapshot.header != 0x18 || snapshot.api != 1 ||
        snapshot.value != NPU_COLD_INDICATION_COUNT || lock_owned || !context() ||
        word(0x3e902aa0u) || word(0x3e901fd4u) ||
        *(const volatile uint8_t *)(uintptr_t)0x3e904590u)
        goto fault;
    if (((int (*)(const uint32_t *))(uintptr_t)0x840064b4u)(&lock_id))
        goto fault;
    lock_owned = 1;
    arena = word(0x3e9030fcu);
    allocation_count = METADATA->count;
    allocation_used = METADATA->used;
    for (i = 0; i < METADATA->count; i++) {
        const struct npu_allocator_entry *entry = &METADATA->entries[i];

        if (entry->type == 1 && !entry->reserved && entry->address == arena) {
            record_index = i;
            matches++;
        }
    }
    if (matches != 1)
        goto fault;
    PLAN->base = arena + 0x1f020u;
    PLAN->bytes = NPU_COLD_INDICATION_BYTES;
    identity[0] = SETUP->sequence;
    identity[1] = SETUP->boot_lo;
    identity[2] = SETUP->boot_hi;
    identity[3] = SETUP->nonce_lo;
    identity[4] = SETUP->nonce_hi;
    if (!owned() || npu_cold_indication_begin(OWNER, PLAN, 1, words()) != NPU_COLD_INDICATION_OK)
        goto fault;
    result = !npu_original_page_dispatch(snapshot.value, 8);
    if (!result || !owned() || word(0x3e902aa0u) != PLAN->base ||
        word(0x3e901fd4u) || *(const volatile uint8_t *)(uintptr_t)0x3e904590u ||
        npu_cold_indication_finish(OWNER, PLAN, 1, words()) != NPU_COLD_INDICATION_OK)
        goto fault;
    goto done;
fault:
    result = fail();
done:
    if (lock_owned) {
        __asm__ volatile ("fence iorw, iorw" ::: "memory");
        ((void (*)(const uint32_t *))(uintptr_t)0x8400651cu)(&lock_id);
        lock_owned = 0;
        if (!context() || word(0x3e9030fcu) != arena ||
            METADATA->count != allocation_count || METADATA->used != allocation_used)
            result = fail();
    }
    __asm__ volatile ("csrw mstatus, %0" :: "r"(status) : "memory");
    return result;
}

state.shared_arena_checks:
/* Native instruction composition, not a production loader/storage contract. */
#include "cold-page.h"
#include "bootstrap.h"

extern struct npu_barrier npu_emulation_barrier_state;
extern struct npu_admission npu_emulation_admission_state;
extern struct npu_bootstrap npu_emulation_bootstrap_state;
extern uint32_t npu_emulation_txdone_callback(const struct npu_bootstrap_packet *);
extern uint32_t npu_original_page_dispatch(uint32_t count, uint32_t selector);
extern uint32_t npu_emulation_indication_callback(const struct npu_bootstrap_packet *);

struct npu_cold_page_state npu_emulation_page_state;
struct npu_cold_page_plan npu_emulation_page_plan;
struct npu_cold_page_queue_result npu_emulation_page_last;
static uint32_t busy;
static uint32_t arena_snapshot;

#define BARRIER (&npu_emulation_barrier_state)
#define ADMISSION (&npu_emulation_admission_state)
#define BOOT (&npu_emulation_bootstrap_state)
#define HEAD 0x3e903950u
#define TAIL 0x3e901f40u
#define POOL 0x3e8a9c70u

static uint32_t word(uint32_t address)
{
    return *(const volatile uint32_t *)(uintptr_t)address;
}

static uint32_t load(const uint32_t *address)
{
    return __atomic_load_n(address, __ATOMIC_ACQUIRE);
}

int npu_emulation_cold_arena_live(void)
{
    uint32_t i, stats = word(0x3e901f08u), arena = word(0x3e9030fcu);

    if (((uint32_t (*)(void))(uintptr_t)0x84004212u)() ||
        load(&BARRIER->request) != 1 || load(&BARRIER->fault) ||
        load(&BARRIER->prepared) || load(&BARRIER->released) || load(&BARRIER->armed) ||
        load(&ADMISSION->closed) != 1 || load(&ADMISSION->fault) ||
        load(&ADMISSION->active) != 1 || BOOT->magic != NPU_BOOTSTRAP_MAGIC ||
        BOOT->failed || BOOT->step != NPU_BOOTSTRAP_STEPS || BOOT->inflight ||
        BOOT->retained_mask != 0x1e ||
        (arena & 31) || arena < 0x3e800000u || arena > 0x3e878000u - 303168u ||
        (arena_snapshot && arena_snapshot != arena) ||
        (stats && ((stats & 3) || stats < 0x3e800000u || stats > 0x3e878000u - 0x4c)) ||
        word(0x3e904634u) != POOL ||
        word(0x3e902ce4u) != BOOT->plan.region[NPU_BOOT_BA].base)
        return 0;
    for (i = 0; i < NPU_BARRIER_WORKERS; i++)
        if (load(&BARRIER->parked[i]) != 1 || load(&BARRIER->ready[i]))
            return 0;
    for (i = 0; i < NPU_BARRIER_DOMAINS; i++)
        if (load(&BARRIER->drained[i]))
            return 0;
    for (i = 0; i < NPU_ADMISSION_IRQ_WORDS; i++)
        if (load(&ADMISSION->deferred[i]))
            return 0;
    return 1;
}

static int live(void)
{
    return npu_emulation_cold_arena_live();
}

state.cold_server:
#include "cold-setup.h"

_Static_assert(sizeof(struct npu_cold_packet) == NPU_COLD_SIZE, "cold wire changed");
_Static_assert(sizeof(struct npu_cold_setup) == 104, "cold owner changed");

static uint32_t load(const uint32_t *word)
{
    return __atomic_load_n(word, __ATOMIC_ACQUIRE);
}

static int held(const struct npu_admission *a, const struct npu_barrier *b,
                const struct npu_bootstrap *boot, uint32_t active)
{
    uint32_t i;

    if (a->closed != 1 || a->active != active || a->fault ||
        !(a->nonce_lo || a->nonce_hi) || load(&b->request) != 1 ||
        load(&b->fault) || load(&b->prepared) || load(&b->released) || load(&b->armed) ||
        boot->magic != NPU_BOOTSTRAP_MAGIC || boot->failed || boot->inflight ||
        boot->step != NPU_BOOTSTRAP_STEPS || boot->retained_mask != 0x1e)
        return 0;
    for (i = 0; i < NPU_BARRIER_WORKERS; i++)
        if (load(&b->parked[i]) != 1 || load(&b->ready[i]))
            return 0;
    for (i = 0; i < NPU_BARRIER_DOMAINS; i++)
        if (load(&b->drained[i]))
            return 0;
    for (i = 0; i < NPU_ADMISSION_IRQ_WORDS; i++)
        if (a->deferred[i])
            return 0;
    return 1;
}

static enum npu_cold_status fail(struct npu_cold_setup *s,
    struct npu_admission *a, struct npu_barrier *b, enum npu_cold_status error)
{
    s->failed = 1;
    npu_admission_fail(a, b);
    return error;
}

static int window(uint32_t base, uint32_t bytes, const struct npu_bootstrap *boot)
{
    uint32_t i;

    if (!npu_cold_endpoint_valid(base, bytes))
        return 0;
    for (i = 0; i < NPU_BOOT_REGIONS; i++) {
        const struct npu_bootstrap_range *r = &boot->plan.region[i];

        if (r->bytes && base < r->base + r->bytes && r->base < base + bytes)
            return 0;
    }
    return 1;
}

static int history(const struct npu_cold_setup *s, const struct npu_bootstrap *boot)
{
    static const uint32_t prefixes[] = {0, 8, 24, 25, 27, 31, 63, 127, 255, 511, 1023, 2047, 4095, 8191, 16383};
    static const uint32_t bits[NPU_COLD_COUNTS] = {NPU_COLD_RX0, NPU_COLD_RX2,
        NPU_COLD_PAGE5, NPU_COLD_PAGE6, NPU_COLD_PAGE7};
    static const uint32_t limits[NPU_COLD_COUNTS] = {1536, 1024, 256, 512, 1024};
    uint32_t i;

    for (i = 0; i < sizeof(prefixes) / sizeof(prefixes[0]); i++)
        if (s->completed == prefixes[i])
            break;
    if (i == sizeof(prefixes) / sizeof(prefixes[0]))
        return 0;
    for (i = 0; i < NPU_COLD_COUNTS; i++) {
        if (s->completed & bits[i]) {
            if (!s->counts[i] || s->counts[i] > limits[i] ||
                ((s->completed & NPU_COLD_ADDR8) && s->counts[i] != limits[i]))
                return 0;
        } else if (s->counts[i]) {
            return 0;
        }
    }
    if (!(s->completed & NPU_COLD_ENDPOINT_BASE))
        return !s->endpoint_base && !s->endpoint_bytes;
    if (!s->endpoint_base || (s->endpoint_base & 4095u) || s->endpoint_base >= 0xc0000000u)
        return 0;
    return s->completed & NPU_COLD_ENDPOINT_BYTES ?
           window(s->endpoint_base, s->endpoint_bytes, boot) : !s->endpoint_bytes;
}

static uint32_t command_bit(const struct npu_bootstrap_packet *p,
                            const struct npu_cold_setup *s, const struct npu_bootstrap *boot)
{
    static const uint32_t limits[] = {256, 512, 1024};
    uint32_t i;

    if (p->header == NPU_COLD_BIND_HEADER && p->api == NPU_COLD_BIND_BASE_API &&
        p->value && !(p->value & 4095u) && p->value < 0xc0000000u)
        return NPU_COLD_ENDPOINT_BASE;
    if (p->header == NPU_COLD_BIND_HEADER && p->api == NPU_COLD_BIND_BYTES_API &&
        window(s->endpoint_base, p->value, boot))
        return NPU_COLD_ENDPOINT_BYTES;
    if (p->header == 0x10 && p->api == 14 && p->value == 2)
        return NPU_COLD_PORT;
    if (p->header == 0x10 && p->api == 1 && p->value && p->value <= 1536)
        return NPU_COLD_RX0;
    if (p->header == 0x12 && p->api == 1 && p->value && p->value <= 1024)
        return NPU_COLD_RX2;
    for (i = 0; i < 3; i++) {
        if (p->header != 0x15u + i)
            continue;
        if (p->api == 0 && window(s->endpoint_base, s->endpoint_bytes, boot) &&
            p->value == s->endpoint_base + NPU_COLD_PAGE_REG0 + 0x10u * i)
            return NPU_COLD_ADDR5 << (i * 2);
        if (p->api == 1 && p->value && p->value <= limits[i])
            return NPU_COLD_PAGE5 << (i * 2);
    }
    if (p->header == 0x18 && p->api == 0 &&
        window(s->endpoint_base, s->endpoint_bytes, boot) &&
        p->value == s->endpoint_base + NPU_COLD_IND_REG)
        return NPU_COLD_ADDR8;
    if (p->header == 0x18 && p->api == 1 && p->value == 1536)
        return NPU_COLD_INDICATION;
    if (p->header == 0x13 && p->api == 19 &&
        window(s->endpoint_base, s->endpoint_bytes, boot) &&
        p->value == s->endpoint_base + NPU_COLD_ACK_REG)
        return NPU_COLD_ACK;
    return 0;
}

static uint32_t prior(uint32_t bit)
{
    switch (bit) {
    case NPU_COLD_ENDPOINT_BASE: return 0;
    case NPU_COLD_ENDPOINT_BYTES: return NPU_COLD_ENDPOINT_BASE;
    case NPU_COLD_PORT: return NPU_COLD_ENDPOINT_BASE | NPU_COLD_ENDPOINT_BYTES;
    case NPU_COLD_RX0: return 25;
    case NPU_COLD_RX2: return 27;
    default: return bit - 1;
    }
}

enum npu_cold_status npu_cold_setup_begin(struct npu_cold_setup *s,
    struct npu_control_v2_session *session, struct npu_admission *a,
    struct npu_barrier *b, const struct npu_bootstrap *boot,
    const struct npu_cold_packet *packet, uint32_t bytes)
{
    struct npu_cold_packet p;
    static const uint32_t limits[NPU_COLD_COUNTS] = {1536, 1024, 256, 512, 1024};
    uint32_t i, bit;

    if (!packet || bytes != sizeof(p))
        return NPU_COLD_BAD_MESSAGE;
    npu_cold_packet_copy(&p, packet);
    if (p.header != NPU_CONTROL_HEADER || p.api != NPU_COLD_API ||
        p.magic != NPU_COLD_REQUEST || p.version != NPU_COLD_VERSION ||
        p.bytes != sizeof(p) || !p.sequence || p.status)
        return NPU_COLD_BAD_MESSAGE;
    for (i = 0; i < 5; i++)
        if (p.reserved[i])
            return NPU_COLD_BAD_MESSAGE;
    if (!(session->boot_lo || session->boot_hi) ||
        p.boot_lo != session->boot_lo || p.boot_hi != session->boot_hi)
        return NPU_COLD_BAD_BOOT;
    if (!(session->nonce_lo || session->nonce_hi) ||
        p.nonce_lo != session->nonce_lo || p.nonce_hi != session->nonce_hi ||
        a->nonce_lo != session->nonce_lo || a->nonce_hi != session->nonce_hi)
        return NPU_COLD_BAD_SESSION;
    if (p.sequence <= session->last_sequence)
        return NPU_COLD_REPLAY;
    /* Reserve before platform/command checks: abandonment never enables replay. */
    session->last_sequence = p.sequence;
    if (s->failed || s->inflight || !history(s, boot) ||
        p.epoch != 1 || !held(a, b, boot, 0))
        return fail(s, a, b, NPU_COLD_BAD_STATE);
    bit = command_bit(&p.command, s, boot);
    if (!bit && !(p.command.header == 0x30 && p.command.api == 10 && !p.command.value))
        return fail(s, a, b, NPU_COLD_UNSUPPORTED);
    if (bit && s->completed != prior(bit))
        return fail(s, a, b, NPU_COLD_BAD_STATE);
    for (i = 0; i < NPU_COLD_COUNTS; i++) {
        if (bit == NPU_COLD_ADDR8 && s->counts[i] != limits[i])
            return fail(s, a, b, NPU_COLD_BAD_STATE);
        s->prior_counts[i] = s->counts[i];
    }
    s->command = p.command;
    s->sequence = p.sequence;
    s->boot_lo = p.boot_lo;
    s->boot_hi = p.boot_hi;
    s->nonce_lo = p.nonce_lo;
    s->nonce_hi = p.nonce_hi;
    s->prior_completed = s->completed;
    s->prior_base = s->endpoint_base;
    s->prior_bytes = s->endpoint_bytes;
    s->inflight = a->active = 1;
    return NPU_COLD_OK;
}

enum npu_cold_status npu_cold_setup_finish(struct npu_cold_setup *s,
    struct npu_control_v2_session *session, struct npu_admission *a,
    struct npu_barrier *b, const struct npu_bootstrap *boot,
    uint32_t result, const struct npu_bootstrap_packet *reply)
{
    static const uint32_t bits[NPU_COLD_COUNTS] = {NPU_COLD_RX0, NPU_COLD_RX2,
        NPU_COLD_PAGE5, NPU_COLD_PAGE6, NPU_COLD_PAGE7};
    uint32_t bit = command_bit(&s->command, s, boot), i;

    for (i = 0; i < NPU_COLD_COUNTS; i++)
        if (s->counts[i] != s->prior_counts[i])
            return fail(s, a, b, NPU_COLD_CALLBACK_FAILED);

    if (s->failed || s->inflight != 1 || !held(a, b, boot, 1) ||
        session->last_sequence != s->sequence ||
        session->boot_lo != s->boot_lo || session->boot_hi != s->boot_hi ||
        session->nonce_lo != s->nonce_lo || session->nonce_hi != s->nonce_hi ||
        a->nonce_lo != s->nonce_lo || a->nonce_hi != s->nonce_hi ||
        s->completed != s->prior_completed || s->endpoint_base != s->prior_base ||
        s->endpoint_bytes != s->prior_bytes || !history(s, boot) ||
        (bit && s->completed != prior(bit)) ||
        (!bit && !(s->command.header == 0x30 && s->command.api == 10 && !s->command.value)) ||
        !reply || result != 1 || reply->header != s->command.header ||
        reply->api != s->command.api ||
        reply->value != (bit ? s->command.value : 0x457u))
        return fail(s, a, b, NPU_COLD_CALLBACK_FAILED);
    if (bit == NPU_COLD_ENDPOINT_BASE)
        s->endpoint_base = s->command.value;
    if (bit == NPU_COLD_ENDPOINT_BYTES)
        s->endpoint_bytes = s->command.value;
    for (i = 0; i < NPU_COLD_COUNTS; i++)
        if (bit == bits[i])
            s->counts[i] = s->command.value;
    s->completed |= bit;
    s->inflight = a->active = 0;
    return NPU_COLD_OK;
}

